#!/usr/bin/env bash
# clear-build: remove dependency and build-output directories (node_modules, dist, ...) across the repo -- **only what git ignores**. For the Requester.
# Usage (from anywhere inside the repo): bash ops/scripts/clear-build.sh        list first, ask once, then delete
#                         bash ops/scripts/clear-build.sh -y     delete without asking
#       Windows: double-click ops\scripts\clear-build.bat (same criterion)
# The project has other build directory names: add them with CLEAR_BUILD_EXTRA="name name" -- do not edit this file (it is FRAME itself; a sync overwrites it).
#
# 【Why this exists】AI sessions install dependencies and produce build output inside the repo; git never takes them,
# yet they stay: every guard that walks the repo walks tens of thousands of extra files (measured: 65% of one
# repo's 25,000 files were git-ignored), and on a mounted disk one full guard run timed out because of it.
# AI sessions have no delete permission by default -- so cleaning up is a one-click job for the Requester.
# 【One criterion: only what git ignores】A matching name is not enough -- **git itself must say "ignored"**:
# the candidates come straight from git (ls-files --others --ignored --directory); the name is only the second filter.
# For a wholly ignored parent (tmp/, say) git reports just the parent, so nothing inside it becomes a candidate --
# tmp/ is the seats' scratch area, and each seat cleans its own.
# 【Why not plain git clean -X】It deletes **everything** ignored: local config, key files, drafts in tmp/ that a seat has not merged back.
set -u
export GIT_OPTIONAL_LOCKS=0
yes=0; case "${1:-}" in -y|--yes|/y) yes=1;; esac
root="$(git rev-parse --show-toplevel 2>/dev/null)" || { echo "not inside a git repository"; exit 2; }
cd "$root" || exit 2
names=" node_modules dist build out .next .nuxt .svelte-kit .turbo .vite .parcel-cache .cache coverage __pycache__ .pytest_cache ${CLEAR_BUILD_EXTRA:-} "

list=()
while IFS= read -r p; do
  case "$p" in */) ;; *) continue;; esac
  d="${p%/}"; b="${d##*/}"
  # The root dist/ does not count: by the ops/ and dist/README.md convention it holds **deliverables** (installers, upgrade packages) that may not be rebuildable on the spot
  [ "$d" = dist ] && continue
  case "$names" in *" $b "*) ;; *) continue;; esac
  # Safety net: never touch a directory holding a tracked file (there should be none when git ignores the whole directory, but a wrong delete cannot be undone)
  [ -z "$(git ls-files -- "$d" 2>/dev/null | head -1)" ] || { echo "  . skipped (holds git-tracked files): $d"; continue; }
  list+=("$d")
done < <(git -c core.quotepath=false ls-files --others --ignored --exclude-standard --directory 2>/dev/null)

if [ "${#list[@]}" -eq 0 ]; then echo "CLEAR-BUILD-OK (no build directory to clean)"; exit 0; fi
echo "These ${#list[@]} directories are ignored by git and named like dependencies or build output; they can go:"
for d in "${list[@]}"; do echo "  $d"; done
if [ "$yes" != 1 ]; then
  a=""; read -r -p "Delete them? Type y and press Enter: " a || true
  case "$a" in y|Y) ;; *) echo "Nothing deleted."; exit 0;; esac
fi
fail=0
for d in "${list[@]}"; do
  rm -rf -- "$d" 2>/dev/null
  if [ -e "$d" ]; then echo "  x could not delete: $d"; fail=$((fail+1)); fi
done
[ "$fail" -eq 0 ] || { echo "CLEAR-BUILD-FAIL ($fail could not be deleted -- usually no delete permission, or a file is in use)"; exit 1; }
echo "CLEAR-BUILD-OK (deleted ${#list[@]} directories; reinstall dependencies and rebuild when you need them)"
